#!/usr/bin/env bash
# Apply 2026-06-25 nv_llm_providers + nv_courts migration as nyvadmin (DATABASE_URL_ADMIN).
set +e
ADM="$(docker exec nyv-gateway printenv DATABASE_URL_ADMIN 2>/dev/null)"
ADM="${ADM%\"}"; ADM="${ADM#\"}"
ADM="$(echo "$ADM" | sed -E 's/sslmode=no-verify/sslmode=require/; s/sslmode=verify-full/sslmode=require/; s/sslmode=verify-ca/sslmode=require/')"
if [ -z "$ADM" ]; then echo "FATAL: DATABASE_URL_ADMIN not set in container"; exit 1; fi
SQL="$(echo '' | base64 -d)"
echo "SQL_BYTES=${#SQL}  ADMIN_URL_LEN=${#ADM}"
docker run --rm --network host -e PGURL="$ADM" -e SQL="$SQL" postgres:16-alpine   sh -c 'psql "$PGURL" -v ON_ERROR_STOP=1 -c "$SQL"' 2>&1
echo "=== verify (as nyvadmin) ==="
docker run --rm --network host -e PGURL="$ADM" postgres:16-alpine   sh -c 'psql "$PGURL" -At -F "|" -c "SELECT (SELECT count(*) FROM nv_llm_providers) providers, (SELECT count(*) FROM nv_courts) courts, (SELECT count(DISTINCT jurisdiction) FROM nv_courts) court_jurs;"' 2>&1
